namespace QorstackReportService.Infrastructure.Services.Document;

/// <summary>
/// Metrics of common Windows/Office fonts (see WordFontMetrics.Data.cs, generated by
/// backend/scripts/font-metrics/gen_word_font_metrics.py from the regular face of each family):
/// <list type="bullet">
/// <item>Single-line height MS Word uses: max(winAscent + winDescent, hhea ascent − descent + lineGap) / unitsPerEm.</item>
/// <item>Advance widths of printable ASCII and the Thai block.</item>
/// </list>
/// Lets us reproduce Word's layout for fonts that a template references but the renderer
/// may not have installed (LibreOffice would measure its fallback font instead).
/// </summary>
internal static partial class WordFontMetrics
{
    private sealed record FontData(double LineHeightEm, Dictionary<char, double> AdvanceEm);

    private static readonly Lazy<Dictionary<string, FontData>> Fonts = new(() =>
        Raw.ToDictionary(kv => kv.Key, kv => Parse(kv.Value), StringComparer.OrdinalIgnoreCase));

    /// <summary>Returns Word's single-line height in em for <paramref name="fontFamily"/>, or null when unknown.</summary>
    public static double? GetLineHeightEm(string? fontFamily) => Find(fontFamily)?.LineHeightEm;

    /// <summary>Returns the space advance width in em for <paramref name="fontFamily"/>, or null when unknown.</summary>
    public static double? GetSpaceWidthEm(string? fontFamily) => GetAdvanceEm(fontFamily, ' ');

    /// <summary>Returns the advance width in em of <paramref name="c"/>, or null when the font or glyph is unknown.</summary>
    public static double? GetAdvanceEm(string? fontFamily, char c) =>
        Find(fontFamily)?.AdvanceEm.TryGetValue(c, out var em) == true ? em : null;

    private static FontData? Find(string? fontFamily) =>
        fontFamily != null && Fonts.Value.TryGetValue(fontFamily.Trim(), out var data) ? data : null;

    private static FontData Parse((double LineHeightEm, int UnitsPerEm, string Advances) raw)
    {
        var codepoints = Enumerable.Range(0x20, 0x7F - 0x20).Concat(Enumerable.Range(0x0E01, 0x0E5C - 0x0E01));
        var advances = new Dictionary<char, double>();
        foreach (var (cp, value) in codepoints.Zip(raw.Advances.Split(',').Select(int.Parse)))
            if (value >= 0) advances[(char)cp] = (double)value / raw.UnitsPerEm;
        return new FontData(raw.LineHeightEm, advances);
    }
}
